cd /testbed && python3 - <<'PY'
from pathlib import Path
p = Path('lucene/core/src/test/org/apache/lucene/document/BaseShapeEncodingTestCase.java')
s = p.read_text()
marker = '  public void testDegeneratedTriangle() {'
assert s.count(marker) == 1
s = s.replace(marker, '''  public void testCollapsedTriangleEdgeFlags() {
    int x0 = encodeX(0);
    int y0 = encodeY(0);
    int x1 = encodeX(1);
    int y1 = encodeY(1);
    int[][] vertices = {
      {x0, y0, x0, y0, x1, y1},
      {x0, y0, x1, y1, x0, y0},
      {x0, y0, x1, y1, x1, y1},
      {x1, y1, x1, y1, x0, y0},
      {x1, y1, x0, y0, x1, y1},
      {x1, y1, x0, y0, x0, y0}
    };
    byte[] bytes = new byte[7 * ShapeField.BYTES];
    ShapeField.DecodedTriangle triangle = new ShapeField.DecodedTriangle();
    for (int[] v : vertices) {
      for (int flags = 0; flags < 8; flags++) {
        boolean ab = (flags & 1) != 0;
        boolean bc = (flags & 2) != 0;
        boolean ca = (flags & 4) != 0;
        boolean expected =
            (ab && (v[0] != v[2] || v[1] != v[3]))
                || (bc && (v[2] != v[4] || v[3] != v[5]))
                || (ca && (v[4] != v[0] || v[5] != v[1]));

        triangle.setValues(v[0], v[1], ab, v[2], v[3], bc, v[4], v[5], ca);
        ShapeField.resolveTriangleType(triangle);
        assertEquals(ShapeField.DecodedTriangle.TYPE.LINE, triangle.type);
        assertEquals(expected, triangle.ab);
        assertEquals(triangle.aX, triangle.cX);
        assertEquals(triangle.aY, triangle.cY);

        ShapeField.encodeTriangle(bytes, v[1], v[0], ab, v[3], v[2], bc, v[5], v[4], ca);
        ShapeField.decodeTriangle(bytes, triangle);
        assertEquals(ShapeField.DecodedTriangle.TYPE.LINE, triangle.type);
        assertEquals(expected, triangle.ab);
        assertEquals(triangle.aX, triangle.cX);
        assertEquals(triangle.aY, triangle.cY);
      }
    }
  }

''' + marker)
p.write_text(s)
p = Path('lucene/core/src/test/org/apache/lucene/document/TestLatLonShape.java')
s = p.read_text()
marker = '  public void testContainsWrappingBooleanQuery() throws Exception {'
assert s.count(marker) == 1
s = s.replace(marker, '''  public void testContainsFlatPolygon() throws Exception {
    Polygon polygon =
        new Polygon(
            new double[] {0, 0, 1e-8, 10, 10, 0},
            new double[] {0, 10, 1e-8, 10, 0, 0});
    try (Directory dir = newDirectory();
        RandomIndexWriter writer = new RandomIndexWriter(random(), dir)) {
      Document document = new Document();
      addPolygonsToDoc(FIELDNAME, document, polygon);
      writer.addDocument(document);
      try (IndexReader reader = writer.getReader()) {
        IndexSearcher searcher = newSearcher(reader);
        LatLonGeometry[] crossing = {
          new Polygon(new double[] {4, 4, 6, 6, 4}, new double[] {-1, 1, 1, -1, -1}),
          new Rectangle(4, 6, -1, 1),
          new Line(new double[] {5, 5}, new double[] {-1, 1})
        };
        for (LatLonGeometry geometry : crossing) {
          assertEquals(
              1,
              searcher.count(
                  LatLonShape.newGeometryQuery(FIELDNAME, QueryRelation.INTERSECTS, geometry)));
          assertEquals(
              0,
              searcher.count(
                  LatLonShape.newGeometryQuery(FIELDNAME, QueryRelation.CONTAINS, geometry)));
        }
        assertEquals(
            1,
            searcher.count(
                LatLonShape.newGeometryQuery(
                    FIELDNAME, QueryRelation.CONTAINS, new Rectangle(7, 8, 1, 2))));
      }
    }
  }

''' + marker)
p.write_text(s)
PY
./gradlew --offline :lucene:core:test --tests org.apache.lucene.document.TestLatLonShapeEncoding.testCollapsedTriangleEdgeFlags --tests org.apache.lucene.document.TestXYShapeEncoding.testCollapsedTriangleEdgeFlags --tests org.apache.lucene.document.TestLatLonShape.testContainsFlatPolygon

